from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq


def _ledger(sequence_first, original_tax):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if sequence_first:
                key = (sequence, event.get("revision", 0), position)
            else:
                key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), mode)
            base = raw if original_tax else net
            tax = rounded(base * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = list(packages)
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    choices = [[-1] + list(rows[name]) for name in names]
    best_key = None
    best = None

    for values in product(*choices):
        installed = dict(zip(names, values))
        if any(installed[name] != version for name, version in pins.items()
               if installed[name] != -1):
            continue
        if any(installed[name] in versions for name, versions in blocked.items()
               if installed[name] != -1):
            continue
        if any(name not in installed or installed[name] < bounds[0]
               or installed[name] > bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {}
        valid = True
        for name, version in installed.items():
            if version == -1:
                continue
            edges[name] = []
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = installed[target]
                if target_version == -1 or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        closure = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in closure:
                continue
            if installed[name] == -1:
                valid = False
                break
            closure.add(name)
            pending.extend(edges[name])
        if not valid or closure != {name for name, v in installed.items() if v != -1}:
            continue

        active, finished = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in closure):
            continue
        key = tuple(installed[name] for name in sorted(names, reverse=True))
        if best_key is None or key < best_key:
            best_key = key
            best = {name: version for name, version in installed.items() if version != -1}

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _scheduling(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in set(data.get("blocked", []))]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for mask in range(1 << len(jobs)):
        selected = [jobs[i] for i in range(len(jobs)) if mask & (1 << i)]
        if len(selected) != k:
            continue
        ids = tuple(sorted(job["id"] for job in selected))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    target = data["target"]
    coupons = data["coupons"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, 0)
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == target and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


SOLVERS = {
    "component_01": _ledger(True, True),
    "component_02": _ledger(False, False),
    "component_03": _ledger(True, False),
    "component_04": _ledger(False, True),
    "component_05": _ledger(True, True),
    "component_06": _dependencies,
    "component_07": _scheduling,
    "component_08": _routes,
}
